import{_ as s,o as t,c as i,a2 as e}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"错误处理与请求追踪","description":"建立稳定错误语义与请求标识，让用户知道如何继续，让团队能从一次失败追到根因。","frontmatter":{"title":"错误处理与请求追踪","description":"建立稳定错误语义与请求标识，让用户知道如何继续，让团队能从一次失败追到根因。"},"headers":[],"relativePath":"backend/error-handling.md","filePath":"backend/error-handling.md","lastUpdated":1786263069000}'),n={name:"backend/error-handling.md"};function l(d,a,p,h,r,o){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="错误处理与请求追踪" tabindex="-1">错误处理与请求追踪 <a class="header-anchor" href="#错误处理与请求追踪" aria-label="Permalink to &quot;错误处理与请求追踪&quot;">​</a></h1><p>错误不是一个统一的“500”。输入不合法、没有权限、资源不存在、依赖超时和程序异常需要不同处理。稳定的错误模型能让客户端做正确分支，也能让服务端更快定位。</p><h2 id="先按责任划分失败" tabindex="-1">先按责任划分失败 <a class="header-anchor" href="#先按责任划分失败" aria-label="Permalink to &quot;先按责任划分失败&quot;">​</a></h2><table tabindex="0"><thead><tr><th>失败类型</th><th>例子</th><th>应如何响应</th></tr></thead><tbody><tr><td>输入问题</td><td>缺少必填字段、格式错误</td><td>指出可修正字段</td></tr><tr><td>身份与权限</td><td>未登录、越权操作</td><td>明确认证或权限状态</td></tr><tr><td>资源状态</td><td>不存在、版本冲突</td><td>告知资源现状或刷新方式</td></tr><tr><td>依赖故障</td><td>数据库、第三方服务超时</td><td>记录上下文，提供重试语义</td></tr><tr><td>程序异常</td><td>未预料分支、代码缺陷</td><td>避免泄露细节，关联请求标识</td></tr></tbody></table><p>服务端内部堆栈和密钥不能直接返回给客户端。对外给出可操作的信息，对内记录排查所需的上下文。</p><h2 id="使用稳定的错误体" tabindex="-1">使用稳定的错误体 <a class="header-anchor" href="#使用稳定的错误体" aria-label="Permalink to &quot;使用稳定的错误体&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;VALIDATION_ERROR&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;请检查提交内容&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;fields&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;标题不能为空&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;requestId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;req_abc123&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>code</code> 给程序判断，<code>message</code> 给用户阅读，<code>fields</code> 支持表单定位，<code>requestId</code> 让支持人员和日志系统能指向同一次请求。字段缺失时应保持兼容，不要让客户端必须猜测。</p><h2 id="请求标识贯穿调用链" tabindex="-1">请求标识贯穿调用链 <a class="header-anchor" href="#请求标识贯穿调用链" aria-label="Permalink to &quot;请求标识贯穿调用链&quot;">​</a></h2><p>入口处生成或接收请求标识，并传到日志、下游调用和错误响应中。一次页面失败时，开发人员可以从标识找到所有相关记录，而不是在海量日志中按时间猜测。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求 req_abc123</span></span>
<span class="line"><span>  → API 日志：解析参数</span></span>
<span class="line"><span>  → 服务日志：创建订单</span></span>
<span class="line"><span>  → 数据库日志：事务回滚</span></span>
<span class="line"><span>  → 响应：requestId=req_abc123</span></span></code></pre></div><h2 id="处理失败不等于无限重试" tabindex="-1">处理失败不等于无限重试 <a class="header-anchor" href="#处理失败不等于无限重试" aria-label="Permalink to &quot;处理失败不等于无限重试&quot;">​</a></h2><p>重试应有次数、退避与总时限；写入操作还要有幂等键或去重策略。无法自动恢复的失败应进入清晰的人工处理或补偿流程。</p><ul><li>记录发生了什么、影响谁、是否可重试。</li><li>对预期业务错误降低日志噪音，对异常错误保留足够上下文。</li><li>定期回顾高频错误，把重复人工处理变成产品提示或代码约束。</li></ul>`,14)])])}const u=s(n,[["render",l]]);export{c as __pageData,u as default};
